// BuyerProcurementAppServiceHandler is an implementation of the
// hawkr.procurement.v1alpha1.BuyerProcurementAppService service.
type BuyerProcurementAppServiceHandler interface {
	// SubmitTurn 送出買家的一則訊息，開始一輪釐清。request_id 空字串表示新建需求。伺服器受理後立刻回 run ID，
	// 這一輪的過程與結果（turn_result 事件）從 WatchRun 取得。這個需求已有進行中的 run 回 FAILED_PRECONDITION，
	// reason 是 PROCUREMENT_RUN_IN_PROGRESS。買家同時進行的 run 已達上限或每分鐘送出已達上限回 resource_exhausted（沒有 reason，帶 RetryInfo，稍後可再試）；
	// 本期額度用完回 resource_exhausted，reason 是 AGENT_MONTHLY_QUOTA_EXCEEDED。
	SubmitTurn(context.Context, *connect.Request[v1alpha1.SubmitTurnRequest]) (*connect.Response[v1alpha1.SubmitTurnResponse], error)
	// GetSnapshot 回傳一張需求目前的內容與狀態。
	GetSnapshot(context.Context, *connect.Request[v1alpha1.GetSnapshotRequest]) (*connect.Response[v1alpha1.GetSnapshotResponse], error)
	// StartCandidateSearch 開始為需求搜尋候選賣家（背景執行，以 GetCandidateSearch 取得結果）。
	// 需求還沒齊備回 FAILED_PRECONDITION，reason 是 REQUIREMENT_NOT_READY；這個需求已有進行中的 run 回 FAILED_PRECONDITION，
	// reason 是 PROCUREMENT_RUN_IN_PROGRESS。買家同時進行的 run 已達上限或每分鐘送出已達上限回 resource_exhausted（沒有 reason，帶 RetryInfo，稍後可再試）。
	StartCandidateSearch(context.Context, *connect.Request[v1alpha1.StartCandidateSearchRequest]) (*connect.Response[v1alpha1.StartCandidateSearchResponse], error)
	// GetCandidateSearch 回傳一次候選搜尋的狀態與目前的候選。
	GetCandidateSearch(context.Context, *connect.Request[v1alpha1.GetCandidateSearchRequest]) (*connect.Response[v1alpha1.GetCandidateSearchResponse], error)
	// ToggleSelection 勾選或取消勾選一個候選。候選所屬的候選集不是有效的候選集（需求已不在 MATCHING，或有更新的搜尋成功）回 ABORTED，conflictTarget 是 candidate_set。
	ToggleSelection(context.Context, *connect.Request[v1alpha1.ToggleSelectionRequest]) (*connect.Response[v1alpha1.ToggleSelectionResponse], error)
	// SubmitAnswer 回答一個釐清問題。需求有待回覆的中斷時改用 ResumeRun，回 FAILED_PRECONDITION，
	// reason 是 APPROVAL_PENDING。只收確定性的回答（選項、數量、略過；品項文字須唯一對到一個末層分類），
	// 品項文字對到多個或零個分類回 INVALID_ARGUMENT（field 是 free_text），請改用 SubmitTurn。
	SubmitAnswer(context.Context, *connect.Request[v1alpha1.SubmitAnswerRequest]) (*connect.Response[v1alpha1.SubmitAnswerResponse], error)
	// Rewind 讓需求退回某個欄位重新回答。有待回覆的中斷時規則同 SubmitAnswer。
	Rewind(context.Context, *connect.Request[v1alpha1.RewindRequest]) (*connect.Response[v1alpha1.RewindResponse], error)
	// PreviewRfqPrice 依買家預期的單價範圍與需求數量，算出詢價總額區間並存成預覽（有效 15 分鐘）。
	// 買家沒有給合法的範圍（下界與上界是正整數、下界不大於上界）回 INVALID_ARGUMENT；
	// 需求已有數量與單位卻算不出總額回 FAILED_PRECONDITION。
	PreviewRfqPrice(context.Context, *connect.Request[v1alpha1.PreviewRfqPriceRequest]) (*connect.Response[v1alpha1.PreviewRfqPriceResponse], error)
	// ConfirmRfqSnapshot 對一份價格預覽產生不可變的詢價確認快照。預覽或需求版本過時回 ABORTED。
	ConfirmRfqSnapshot(context.Context, *connect.Request[v1alpha1.ConfirmRfqSnapshotRequest]) (*connect.Response[v1alpha1.ConfirmRfqSnapshotResponse], error)
	// PreviewRfqPublication 依確認快照編出要發給賣家的內容並建立不可變的發布核准，不發布、不通知。
	PreviewRfqPublication(context.Context, *connect.Request[v1alpha1.PreviewRfqPublicationRequest]) (*connect.Response[v1alpha1.PreviewRfqPublicationResponse], error)
	// ExecuteRfqPublication 以發布核准的版本執行發布。成功只代表伺服器已建立發布，不代表已投遞或賣家已看到。
	ExecuteRfqPublication(context.Context, *connect.Request[v1alpha1.ExecuteRfqPublicationRequest]) (*connect.Response[v1alpha1.ExecuteRfqPublicationResponse], error)
	// ListConversations 列出買家的對話，最近更新的在前。
	ListConversations(context.Context, *connect.Request[v1alpha1.ListConversationsRequest]) (*connect.Response[v1alpha1.ListConversationsResponse], error)
	GetConversationMessages(context.Context, *connect.Request[v1alpha1.GetConversationMessagesRequest]) (*connect.Response[v1alpha1.GetConversationMessagesResponse], error)
	// GetRuntimeSnapshot 回傳重建一個對話畫面需要的全部事實：訊息、run、待回覆的中斷與發布結果。
	GetRuntimeSnapshot(context.Context, *connect.Request[v1alpha1.GetRuntimeSnapshotRequest]) (*connect.Response[v1alpha1.GetRuntimeSnapshotResponse], error)
	// ListSellerResponses 列出一張需求已發布的詢價收到的賣家回價（每位賣家的目前版本）。
	ListSellerResponses(context.Context, *connect.Request[v1alpha1.ListSellerResponsesRequest]) (*connect.Response[v1alpha1.ListSellerResponsesResponse], error)
	// PutShortlistEntry 把賣家回價的一個版本加入入圍清單；已在清單時回目前的狀態。
	PutShortlistEntry(context.Context, *connect.Request[v1alpha1.PutShortlistEntryRequest]) (*connect.Response[v1alpha1.PutShortlistEntryResponse], error)
	// DeleteShortlistEntry 把賣家回價從入圍清單移除；不在清單時回目前的狀態。
	DeleteShortlistEntry(context.Context, *connect.Request[v1alpha1.DeleteShortlistEntryRequest]) (*connect.Response[v1alpha1.DeleteShortlistEntryResponse], error)
	// AcceptSellerQuote 接受賣家回價的指定版本並凍結成交價，隨後建立待付款訂單。報價已改版、已撤回回 ABORTED，
	// conflictTarget 是 seller_response；報價已過有效期回 FAILED_PRECONDITION，reason 是 RFQ_RESPONSE_EXPIRED；
	// 同一張需求已有進行中的成交回 FAILED_PRECONDITION，reason 是 RFQ_CHECKOUT_ALREADY_ACTIVE（metadata 的 orderNo 是
	// 既有訂單，買家去付款，不是重新接受）；已經成交回 FAILED_PRECONDITION，reason 是 RFQ_ALREADY_AWARDED。
	AcceptSellerQuote(context.Context, *connect.Request[v1alpha1.AcceptSellerQuoteRequest]) (*connect.Response[v1alpha1.AcceptSellerQuoteResponse], error)
	RenameConversation(context.Context, *connect.Request[v1alpha1.RenameConversationRequest]) (*connect.Response[v1alpha1.RenameConversationResponse], error)
	DeleteConversation(context.Context, *connect.Request[v1alpha1.DeleteConversationRequest]) (*connect.Response[v1alpha1.DeleteConversationResponse], error)
	// WatchRun 訂閱一個 run 的事件，從 cursor 之後開始（空字串表示從頭）。只讀；伺服器在 run 結束（finished 或 error 事件之後）
	// 或滿 100 秒時結束串流。每位買家同時訂閱的串流有上限，超過回 resource_exhausted。
	WatchRun(context.Context, *connect.Request[v1alpha1.WatchRunRequest], *connect.ServerStream[v1alpha1.WatchRunResponse]) error
	// CancelRun 取消一個進行中的 run。run 已不在進行中不會回錯，cancel_disposition 說明結果。
	CancelRun(context.Context, *connect.Request[v1alpha1.CancelRunRequest]) (*connect.Response[v1alpha1.CancelRunResponse], error)
	// ResumeRun 回覆 run 停下來等待的中斷，從中斷處接續，排入回答 run 後立即回傳 run_id。回覆格式不合
	// （option_id 與 free_text 要恰一個、文字不可只有空白、選項要在待回答的卡上）回 INVALID_ARGUMENT 並帶欄位違規。中斷已被回覆回 FAILED_PRECONDITION，
	// reason 是 APPROVAL_ALREADY_RESOLVED；run 不在等待輸入的狀態回 FAILED_PRECONDITION，reason 是 RUN_NOT_ACTIVE；
	// 這個需求已有進行中的 run（包含另一個正在回答的 run）回 FAILED_PRECONDITION，reason 是 PROCUREMENT_RUN_IN_PROGRESS。
	// 買家同時進行的 run 已達上限或每分鐘送出已達上限回 resource_exhausted（沒有 reason，帶 RetryInfo，稍後可再試）。
	ResumeRun(context.Context, *connect.Request[v1alpha1.ResumeRunRequest]) (*connect.Response[v1alpha1.ResumeRunResponse], error)
}

